window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ae1c21122b64f549"]={"versions": [{"id": "FIG-ae1c21122b64f549", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (<code>class UnitType</code>) des AUTOSAR-Metamodells (M2-Ebene).\n</li><li><strong>Architektur-Kontext:</strong> Definition der semantischen Metadaten zur physikalischen Dimensionierung und Einheitenbeschreibung von Applikationsdaten, Signalen und Kalibriergrößen. Es dient zur formalen Standardisierung von Messgrößen in Software-Component-Descriptions (SWCD), Schnittstellenverträgen (Port-Interfaces) und dem Export für Mess- und Kalibriersysteme (ASAM MCD-2 MC / A2L).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>Unit</code></strong> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Zentrales Paket-Element zur Definition konkreter technischer Maßeinheiten (z. B. km/h, ^∘ C, bar).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>factorSiToUnit: Float [0..1]</code> – Multiplikativer Skalierungsfaktor zur Umrechnung zwischen der abgeleiteten SI-Einheit und der spezifischen Einheit.\n</li><li><code>offsetSiToUnit: Float [0..1]</code> – Additiver Offset für affine Umrechnungen (z. B. Umrechnung zwischen Kelvin und Grad Celsius).\n</li></ul>\n</li></ul>\n</li><li><strong><code>PhysicalDimension</code></strong> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Formalisiert die physikalische Dimension anhand der Potenzen der sieben SI-Basiseinheiten (kg, m, s, A, K, mol, cd).\n</li><li>Attribute (alle ganzzahlig, optional):\n<ul class=\"fig-list\"><li><code>lengthExp: Integer [0..1]</code> – Exponent der Basiseinheit Meter (m).\n</li><li><code>massExp: Integer [0..1]</code> – Exponent der Basiseinheit Kilogramm (kg).\n</li><li><code>timeExp: Integer [0..1]</code> – Exponent der Basiseinheit Sekunde (s).\n</li><li><code>currentExp: Integer [0..1]</code> – Exponent der Basiseinheit Ampere (A).\n</li><li><code>temperatureExp: Integer [0..1]</code> – Exponent der Basiseinheit Kelvin (K).\n</li><li><code>molarAmountExp: Integer [0..1]</code> – Exponent der Basiseinheit Mol (mol).\n</li><li><code>luminousIntensityExp: Integer [0..1]</code> – Exponent der Basiseinheit Candela (cd).\n</li></ul>\n</li></ul>\n</li><li><strong><code>SingleLanguageData::SingleLanguageUnitNames</code></strong> (Stereotyp: <code>«atpMixedString»</code>, Subtyp/Spezialisierung: <code>MixedContentForUnitNames</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die typografische bzw. sprachspezifische Textdarstellung der Einheit (z. B. Formelzeichen, Einheitenstrings wie „m/s^2“).\n</li></ul>\n</li><li><strong><code>Chapters::PredefinedChapter</code></strong>:\n<ul class=\"fig-list\"><li>Strukturiertes Dokumentationselement zur Erfassung redaktioneller oder normativer Zusatzinformationen.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>Unit</code> $\\blacklozenge\\xrightarrow{\\text{+displayName}} [0..1]$ <code>SingleLanguageUnitNames</code>:</strong> Strenge Komposition zur Kapselung des primären Anzeigenamens.\n</li><li><strong><code>Unit</code> $\\blacklozenge\\xrightarrow{\\text{+addInfo}} [0..1]$ <code>PredefinedChapter</code>:</strong> Strenge Komposition zur Einbettung begleitender Dokumentationskapitel.\n</li><li><strong><code>Unit</code> $\\xrightarrow{\\text{+physicalDimension}} [0..1]$ <code>PhysicalDimension</code>:</strong> Unidirektionale Referenz (Assoziation) zur Verknüpfung der Einheit mit ihrer zugrunde liegenden SI-Basisdimension.\n</li><li>Sowohl <code>Unit</code> als auch <code>PhysicalDimension</code> sind eigenständige <code>ARElement</code>-Objekte und können modular in ARXML-Paketen referenziert und wiederverwendet werden.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm definiert Datenstrukturen für die Entwurfs- und Generierungszeit.\n</li><li><strong>Toolchain-Verarbeitung:</strong> \n<ul class=\"fig-list\"><li>Konsistenzprüfungen während der SWC-Komposition: Werkzeuge validieren über <code>physicalDimension</code>, ob verknüpfte Sender-/Receiver-Ports physikalisch kompatibel sind.\n</li><li>Generierung von Transformationsfunktionen: Bei gleicher <code>physicalDimension</code>, aber abweichenden <code>Unit</code>-Definitionen (z. B. m/s vs. km/h), können Toolchains Konvertierungs-Routinen in der RTE oder Adapter-Komponenten anfordern.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Keine Laufzeit-Repräsentation im C-Code:</strong> <code>Unit</code> und <code>PhysicalDimension</code> erzeugen keine C-Typen im RTE- oder BSW-Stack; sie sind reine Entwurfszeit- und Kalibriermetadaten.\n</li><li><strong>A2L-Generierung (MCD-Schnittstelle):</strong> Dient Generatoren als Basis für die automatische Erstellung von <code>UNIT</code>- und <code>COMPU_METHOD</code>-Blöcken in ASAM-MCD-2MC-Dateien (.a2l).\n</li><li><strong>Standard-Konvention für Skalierung:</strong>\n<ul class=\"fig-list\"><li>Fehlende Attribute (<code>factorSiToUnit</code>, <code>offsetSiToUnit</code>) implizieren den Default-Wert 1.0 (Faktor) bzw. 0.0 (Offset).\n</li><li>Umrechnungsgleichung gemäß AUTOSAR-Spezifikation:\n $$\\text{Wert}_{\\text{Unit}} = \\text{Wert}_{\\text{SI}} \\cdot \\text{factorSiToUnit} + \\text{offsetSiToUnit}$$\n</li></ul>\n</li><li><strong>Port-Kompatibilität:</strong> Entwickler müssen sicherstellen, dass Port-Interfaces konsistente <code>Unit</code>-Referenzen deklarieren, um Fehlwarnungen statischer Modellprüfer (Model Verifier) bei Interface-Mappings zu verhindern.\n</li></ul>"}, {"id": "FIG-ee70a8b8fe921ec4", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (<code>class UnitType</code>) des AUTOSAR-Metamodells (M2-Ebene).\n</li><li><strong>Architektur-Kontext:</strong> Definition der semantischen Metadaten zur physikalischen Dimensionierung und Einheitenbeschreibung von Applikationsdaten, Signalen und Kalibriergrößen. Es dient zur formalen Standardisierung von Messgrößen in Software-Component-Descriptions (SWCD), Schnittstellenverträgen (Port-Interfaces) und dem Export für Mess- und Kalibriersysteme (ASAM MCD-2 MC / A2L).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>Unit</code></strong> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Zentrales Paket-Element zur Definition konkreter technischer Maßeinheiten (z. B. km/h, ^∘ C, bar).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>factorSiToUnit: Float [0..1]</code> – Multiplikativer Skalierungsfaktor zur Umrechnung zwischen der abgeleiteten SI-Einheit und der spezifischen Einheit.\n</li><li><code>offsetSiToUnit: Float [0..1]</code> – Additiver Offset für affine Umrechnungen (z. B. Umrechnung zwischen Kelvin und Grad Celsius).\n</li></ul>\n</li></ul>\n</li><li><strong><code>PhysicalDimension</code></strong> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Formalisiert die physikalische Dimension anhand der Potenzen der sieben SI-Basiseinheiten (kg, m, s, A, K, mol, cd).\n</li><li>Attribute (alle ganzzahlig, optional):\n<ul class=\"fig-list\"><li><code>lengthExp: Integer [0..1]</code> – Exponent der Basiseinheit Meter (m).\n</li><li><code>massExp: Integer [0..1]</code> – Exponent der Basiseinheit Kilogramm (kg).\n</li><li><code>timeExp: Integer [0..1]</code> – Exponent der Basiseinheit Sekunde (s).\n</li><li><code>currentExp: Integer [0..1]</code> – Exponent der Basiseinheit Ampere (A).\n</li><li><code>temperatureExp: Integer [0..1]</code> – Exponent der Basiseinheit Kelvin (K).\n</li><li><code>molarAmountExp: Integer [0..1]</code> – Exponent der Basiseinheit Mol (mol).\n</li><li><code>luminousIntensityExp: Integer [0..1]</code> – Exponent der Basiseinheit Candela (cd).\n</li></ul>\n</li></ul>\n</li><li><strong><code>SingleLanguageData::SingleLanguageUnitNames</code></strong> (Stereotyp: <code>«atpMixedString»</code>, Subtyp/Spezialisierung: <code>MixedContentForUnitNames</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die typografische bzw. sprachspezifische Textdarstellung der Einheit (z. B. Formelzeichen, Einheitenstrings wie „m/s^2“).\n</li></ul>\n</li><li><strong><code>Chapters::PredefinedChapter</code></strong>:\n<ul class=\"fig-list\"><li>Strukturiertes Dokumentationselement zur Erfassung redaktioneller oder normativer Zusatzinformationen.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>Unit</code> $\\blacklozenge\\xrightarrow{\\text{+displayName}} [0..1]$ <code>SingleLanguageUnitNames</code>:</strong> Strenge Komposition zur Kapselung des primären Anzeigenamens.\n</li><li><strong><code>Unit</code> $\\blacklozenge\\xrightarrow{\\text{+addInfo}} [0..1]$ <code>PredefinedChapter</code>:</strong> Strenge Komposition zur Einbettung begleitender Dokumentationskapitel.\n</li><li><strong><code>Unit</code> $\\xrightarrow{\\text{+physicalDimension}} [0..1]$ <code>PhysicalDimension</code>:</strong> Unidirektionale Referenz (Assoziation) zur Verknüpfung der Einheit mit ihrer zugrunde liegenden SI-Basisdimension.\n</li><li>Sowohl <code>Unit</code> als auch <code>PhysicalDimension</code> sind eigenständige <code>ARElement</code>-Objekte und können modular in ARXML-Paketen referenziert und wiederverwendet werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm definiert Datenstrukturen für die Entwurfs- und Generierungszeit.\n</li><li><strong>Toolchain-Verarbeitung:</strong> \n<ul class=\"fig-list\"><li>Konsistenzprüfungen während der SWC-Komposition: Werkzeuge validieren über <code>physicalDimension</code>, ob verknüpfte Sender-/Receiver-Ports physikalisch kompatibel sind.\n</li><li>Generierung von Transformationsfunktionen: Bei gleicher <code>physicalDimension</code>, aber abweichenden <code>Unit</code>-Definitionen (z. B. m/s vs. km/h), können Toolchains Konvertierungs-Routinen in der RTE oder Adapter-Komponenten anfordern.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Keine Laufzeit-Repräsentation im C-Code:</strong> <code>Unit</code> und <code>PhysicalDimension</code> erzeugen keine C-Typen im RTE- oder BSW-Stack; sie sind reine Entwurfszeit- und Kalibriermetadaten.\n</li><li><strong>A2L-Generierung (MCD-Schnittstelle):</strong> Dient Generatoren als Basis für die automatische Erstellung von <code>UNIT</code>- und <code>COMPU_METHOD</code>-Blöcken in ASAM-MCD-2MC-Dateien (.a2l).\n</li><li><strong>Standard-Konvention für Skalierung:</strong>\n<ul class=\"fig-list\"><li>Fehlende Attribute (<code>factorSiToUnit</code>, <code>offsetSiToUnit</code>) implizieren den Default-Wert 1.0 (Faktor) bzw. 0.0 (Offset).\n</li><li>Umrechnungsgleichung gemäß AUTOSAR-Spezifikation:\n $$\\text{Wert}_{\\text{Unit}} = \\text{Wert}_{\\text{SI}} \\cdot \\text{factorSiToUnit} + \\text{offsetSiToUnit}$$\n</li></ul>\n</li><li><strong>Port-Kompatibilität:</strong> Entwickler müssen sicherstellen, dass Port-Interfaces konsistente <code>Unit</code>-Referenzen deklarieren, um Fehlwarnungen statischer Modellprüfer (Model Verifier) bei Interface-Mappings zu verhindern.\n</li></ul>"}, {"id": "FIG-056fb60c476e337c", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (<code>class UnitType</code>) des AUTOSAR-Metamodells (M2-Ebene).\n</li><li><strong>Architektur-Kontext:</strong> Definition der semantischen Metadaten zur physikalischen Dimensionierung und Einheitenbeschreibung von Applikationsdaten, Signalen und Kalibriergrößen. Es dient zur formalen Standardisierung von Messgrößen in Software-Component-Descriptions (SWCD), Schnittstellenverträgen (Port-Interfaces) und dem Export für Mess- und Kalibriersysteme (ASAM MCD-2 MC / A2L).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>Unit</code></strong> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Zentrales Paket-Element zur Definition konkreter technischer Maßeinheiten (z. B. km/h, ^∘ C, bar).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>factorSiToUnit: Float [0..1]</code> – Multiplikativer Skalierungsfaktor zur Umrechnung zwischen der abgeleiteten SI-Einheit und der spezifischen Einheit.\n</li><li><code>offsetSiToUnit: Float [0..1]</code> – Additiver Offset für affine Umrechnungen (z. B. Umrechnung zwischen Kelvin und Grad Celsius).\n</li></ul>\n</li></ul>\n</li><li><strong><code>PhysicalDimension</code></strong> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Formalisiert die physikalische Dimension anhand der Potenzen der sieben SI-Basiseinheiten (kg, m, s, A, K, mol, cd).\n</li><li>Attribute (alle ganzzahlig, optional):\n<ul class=\"fig-list\"><li><code>lengthExp: Integer [0..1]</code> – Exponent der Basiseinheit Meter (m).\n</li><li><code>massExp: Integer [0..1]</code> – Exponent der Basiseinheit Kilogramm (kg).\n</li><li><code>timeExp: Integer [0..1]</code> – Exponent der Basiseinheit Sekunde (s).\n</li><li><code>currentExp: Integer [0..1]</code> – Exponent der Basiseinheit Ampere (A).\n</li><li><code>temperatureExp: Integer [0..1]</code> – Exponent der Basiseinheit Kelvin (K).\n</li><li><code>molarAmountExp: Integer [0..1]</code> – Exponent der Basiseinheit Mol (mol).\n</li><li><code>luminousIntensityExp: Integer [0..1]</code> – Exponent der Basiseinheit Candela (cd).\n</li></ul>\n</li></ul>\n</li><li><strong><code>SingleLanguageData::SingleLanguageUnitNames</code></strong> (Stereotyp: <code>«atpMixedString»</code>, Subtyp/Spezialisierung: <code>MixedContentForUnitNames</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die typografische bzw. sprachspezifische Textdarstellung der Einheit (z. B. Formelzeichen, Einheitenstrings wie „m/s^2“).\n</li></ul>\n</li><li><strong><code>Chapters::PredefinedChapter</code></strong>:\n<ul class=\"fig-list\"><li>Strukturiertes Dokumentationselement zur Erfassung redaktioneller oder normativer Zusatzinformationen.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>Unit</code> $\\blacklozenge\\xrightarrow{\\text{+displayName}} [0..1]$ <code>SingleLanguageUnitNames</code>:</strong> Strenge Komposition zur Kapselung des primären Anzeigenamens.\n</li><li><strong><code>Unit</code> $\\blacklozenge\\xrightarrow{\\text{+addInfo}} [0..1]$ <code>PredefinedChapter</code>:</strong> Strenge Komposition zur Einbettung begleitender Dokumentationskapitel.\n</li><li><strong><code>Unit</code> $\\xrightarrow{\\text{+physicalDimension}} [0..1]$ <code>PhysicalDimension</code>:</strong> Unidirektionale Referenz (Assoziation) zur Verknüpfung der Einheit mit ihrer zugrunde liegenden SI-Basisdimension.\n</li><li>Sowohl <code>Unit</code> als auch <code>PhysicalDimension</code> sind eigenständige <code>ARElement</code>-Objekte und können modular in ARXML-Paketen referenziert und wiederverwendet werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm definiert Datenstrukturen für die Entwurfs- und Generierungszeit.\n</li><li><strong>Toolchain-Verarbeitung:</strong> \n<ul class=\"fig-list\"><li>Konsistenzprüfungen während der SWC-Komposition: Werkzeuge validieren über <code>physicalDimension</code>, ob verknüpfte Sender-/Receiver-Ports physikalisch kompatibel sind.\n</li><li>Generierung von Transformationsfunktionen: Bei gleicher <code>physicalDimension</code>, aber abweichenden <code>Unit</code>-Definitionen (z. B. m/s vs. km/h), können Toolchains Konvertierungs-Routinen in der RTE oder Adapter-Komponenten anfordern.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Keine Laufzeit-Repräsentation im C-Code:</strong> <code>Unit</code> und <code>PhysicalDimension</code> erzeugen keine C-Typen im RTE- oder BSW-Stack; sie sind reine Entwurfszeit- und Kalibriermetadaten.\n</li><li><strong>A2L-Generierung (MCD-Schnittstelle):</strong> Dient Generatoren als Basis für die automatische Erstellung von <code>UNIT</code>- und <code>COMPU_METHOD</code>-Blöcken in ASAM-MCD-2MC-Dateien (.a2l).\n</li><li><strong>Standard-Konvention für Skalierung:</strong>\n<ul class=\"fig-list\"><li>Fehlende Attribute (<code>factorSiToUnit</code>, <code>offsetSiToUnit</code>) implizieren den Default-Wert 1.0 (Faktor) bzw. 0.0 (Offset).\n</li><li>Umrechnungsgleichung gemäß AUTOSAR-Spezifikation:\n $$\\text{Wert}_{\\text{Unit}} = \\text{Wert}_{\\text{SI}} \\cdot \\text{factorSiToUnit} + \\text{offsetSiToUnit}$$\n</li></ul>\n</li><li><strong>Port-Kompatibilität:</strong> Entwickler müssen sicherstellen, dass Port-Interfaces konsistente <code>Unit</code>-Referenzen deklarieren, um Fehlwarnungen statischer Modellprüfer (Model Verifier) bei Interface-Mappings zu verhindern.\n</li></ul>"}, {"id": "FIG-f8ed3e93f1583fc0", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (<code>class UnitType</code>) des AUTOSAR-Metamodells (M2-Ebene).\n</li><li><strong>Architektur-Kontext:</strong> Definition der semantischen Metadaten zur physikalischen Dimensionierung und Einheitenbeschreibung von Applikationsdaten, Signalen und Kalibriergrößen. Es dient zur formalen Standardisierung von Messgrößen in Software-Component-Descriptions (SWCD), Schnittstellenverträgen (Port-Interfaces) und dem Export für Mess- und Kalibriersysteme (ASAM MCD-2 MC / A2L).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>Unit</code></strong> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Zentrales Paket-Element zur Definition konkreter technischer Maßeinheiten (z. B. km/h, ^∘ C, bar).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>factorSiToUnit: Float [0..1]</code> – Multiplikativer Skalierungsfaktor zur Umrechnung zwischen der abgeleiteten SI-Einheit und der spezifischen Einheit.\n</li><li><code>offsetSiToUnit: Float [0..1]</code> – Additiver Offset für affine Umrechnungen (z. B. Umrechnung zwischen Kelvin und Grad Celsius).\n</li></ul>\n</li></ul>\n</li><li><strong><code>PhysicalDimension</code></strong> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Formalisiert die physikalische Dimension anhand der Potenzen der sieben SI-Basiseinheiten (kg, m, s, A, K, mol, cd).\n</li><li>Attribute (alle ganzzahlig, optional):\n<ul class=\"fig-list\"><li><code>lengthExp: Integer [0..1]</code> – Exponent der Basiseinheit Meter (m).\n</li><li><code>massExp: Integer [0..1]</code> – Exponent der Basiseinheit Kilogramm (kg).\n</li><li><code>timeExp: Integer [0..1]</code> – Exponent der Basiseinheit Sekunde (s).\n</li><li><code>currentExp: Integer [0..1]</code> – Exponent der Basiseinheit Ampere (A).\n</li><li><code>temperatureExp: Integer [0..1]</code> – Exponent der Basiseinheit Kelvin (K).\n</li><li><code>molarAmountExp: Integer [0..1]</code> – Exponent der Basiseinheit Mol (mol).\n</li><li><code>luminousIntensityExp: Integer [0..1]</code> – Exponent der Basiseinheit Candela (cd).\n</li></ul>\n</li></ul>\n</li><li><strong><code>SingleLanguageData::SingleLanguageUnitNames</code></strong> (Stereotyp: <code>«atpMixedString»</code>, Subtyp/Spezialisierung: <code>MixedContentForUnitNames</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die typografische bzw. sprachspezifische Textdarstellung der Einheit (z. B. Formelzeichen, Einheitenstrings wie „m/s^2“).\n</li></ul>\n</li><li><strong><code>Chapters::PredefinedChapter</code></strong>:\n<ul class=\"fig-list\"><li>Strukturiertes Dokumentationselement zur Erfassung redaktioneller oder normativer Zusatzinformationen.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>Unit</code> $\\blacklozenge\\xrightarrow{\\text{+displayName}} [0..1]$ <code>SingleLanguageUnitNames</code>:</strong> Strenge Komposition zur Kapselung des primären Anzeigenamens.\n</li><li><strong><code>Unit</code> $\\blacklozenge\\xrightarrow{\\text{+addInfo}} [0..1]$ <code>PredefinedChapter</code>:</strong> Strenge Komposition zur Einbettung begleitender Dokumentationskapitel.\n</li><li><strong><code>Unit</code> $\\xrightarrow{\\text{+physicalDimension}} [0..1]$ <code>PhysicalDimension</code>:</strong> Unidirektionale Referenz (Assoziation) zur Verknüpfung der Einheit mit ihrer zugrunde liegenden SI-Basisdimension.\n</li><li>Sowohl <code>Unit</code> als auch <code>PhysicalDimension</code> sind eigenständige <code>ARElement</code>-Objekte und können modular in ARXML-Paketen referenziert und wiederverwendet werden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm definiert Datenstrukturen für die Entwurfs- und Generierungszeit.\n</li><li><strong>Toolchain-Verarbeitung:</strong> \n<ul class=\"fig-list\"><li>Konsistenzprüfungen während der SWC-Komposition: Werkzeuge validieren über <code>physicalDimension</code>, ob verknüpfte Sender-/Receiver-Ports physikalisch kompatibel sind.\n</li><li>Generierung von Transformationsfunktionen: Bei gleicher <code>physicalDimension</code>, aber abweichenden <code>Unit</code>-Definitionen (z. B. m/s vs. km/h), können Toolchains Konvertierungs-Routinen in der RTE oder Adapter-Komponenten anfordern.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Keine Laufzeit-Repräsentation im C-Code:</strong> <code>Unit</code> und <code>PhysicalDimension</code> erzeugen keine C-Typen im RTE- oder BSW-Stack; sie sind reine Entwurfszeit- und Kalibriermetadaten.\n</li><li><strong>A2L-Generierung (MCD-Schnittstelle):</strong> Dient Generatoren als Basis für die automatische Erstellung von <code>UNIT</code>- und <code>COMPU_METHOD</code>-Blöcken in ASAM-MCD-2MC-Dateien (.a2l).\n</li><li><strong>Standard-Konvention für Skalierung:</strong>\n<ul class=\"fig-list\"><li>Fehlende Attribute (<code>factorSiToUnit</code>, <code>offsetSiToUnit</code>) implizieren den Default-Wert 1.0 (Faktor) bzw. 0.0 (Offset).\n</li><li>Umrechnungsgleichung gemäß AUTOSAR-Spezifikation:\n $$\\text{Wert}_{\\text{Unit}} = \\text{Wert}_{\\text{SI}} \\cdot \\text{factorSiToUnit} + \\text{offsetSiToUnit}$$\n</li></ul>\n</li><li><strong>Port-Kompatibilität:</strong> Entwickler müssen sicherstellen, dass Port-Interfaces konsistente <code>Unit</code>-Referenzen deklarieren, um Fehlwarnungen statischer Modellprüfer (Model Verifier) bei Interface-Mappings zu verhindern.\n</li></ul>"}], "trans": [{"from": "FIG-ae1c21122b64f549", "to": "FIG-ee70a8b8fe921ec4", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ee70a8b8fe921ec4", "to": "FIG-056fb60c476e337c", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-056fb60c476e337c", "to": "FIG-f8ed3e93f1583fc0", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
